mapper.select:
SELECT g.id, g.voucher_no AS voucherNo, g.eir_id AS eirId, e.eir_no AS eirNo, g.appointment_id AS appointmentId, g.check_time AS checkTime, g.result, g.abnormal_type AS abnormalType, g.operator_id AS operatorId, u.name AS operatorName, g.remark FROM gate_check_log g LEFT JOIN eir_order e ON e.id = g.eir_id LEFT JOIN sys_user u ON u.id = g.operator_id
AND g.result = #{result}
ORDER BY g.id DESC LIMIT #{offset}, #{size}
